        if record.pn in self.pn_sets[number_space]:
            self._set_result(record, "duplicate", "DUPLICATE", time)
            return

        self._processing_level = record.level
        try:
            self._preflight(record.frames)
            transaction, close = self._semantics(record.frames)
        except PacketFailure as failure:
            # _semantics only exposes its transaction on success, so semantic
            # rollback is performed in the wrapper below via _active_transaction.
            self._set_result(record, "error", failure.code, time, failure.frame)
            self._terminate(
                "closed", failure.code, time,
                {"event": record.event, "packet": record.packet, "frame": failure.frame},
            )
            return

        self.pn_sets[number_space].add(record.pn)
        self.last_activity = time
        self._set_result(record, "accepted", "OK", time)
        if close is not None:
            self._terminate(
                "closed",
                "PEER_APPLICATION_CLOSE" if close["app"] else "PEER_TRANSPORT_CLOSE",
                time,
                {"event": record.event, "packet": record.packet, "frame": self._frame_index},
                close["code"],
            )

    def _process_packet(self, record, time):
        """Process a packet whose keys are live, with atomic frame effects."""
        # This wrapper installs a transaction rollback hook without copying any
        # of the potentially large sparse reassembly maps.
        if not record.auth:
            self._set_result(record, "dropped", "AUTH", time)
            return
        number_space = record.level if record.level in ("I", "H") else "A"
        if record.pn in self.pn_sets[number_space]:
            self._set_result(record, "duplicate", "DUPLICATE", time)
            return

        self._processing_level = record.level
        try:
            self._preflight(record.frames)
        except PacketFailure as failure:
            self._packet_error(record, failure, time)
            return

        transaction = Transaction(self)
        try:
            close = None
            for index, frame in enumerate(record.frames):
                self._frame_index = index
                kind = frame["type"]
                if kind in ("PADDING", "PING"):
                    continue
                if kind == "STREAM":
                    self._stream_frame(frame, transaction)
                elif kind == "RESET_STREAM":
                    self._reset_frame(frame, transaction)
                elif kind == "STOP_SENDING":
                    self._stop_frame(frame, transaction)
                elif kind == "CRYPTO":
                    self._crypto_frame(frame, transaction)
                elif kind == "ACK":
                    self._ack_frame(frame)
                elif kind == "CLOSE":
                    close = frame
                    break
