        if sid not in self.streams:
            old = self.receiver.streams.get(sid)
            if old is None:
                self.streams[sid] = None
                old = StreamState()
                self.receiver.streams[sid] = old
            else:
                self.streams[sid] = (
                    old.highest, old.final_size, old.reset, old.stopped, len(old.delivered)
