    _integer(config["idle_ms"], 0, 1000000000)
    _integer(config["max_streams_bidi"], 0, 1024)
    _integer(config["max_streams_uni"], 0, 1024)
    _integer(config["max_stream_data"], 0, 65536)
    _integer(config["max_data"])
    _integer(config["crypto_limit"], 0, 65536)
